// 走査順にアルキメデス螺旋へ並べる。
// 引数 tree は { id, collapsed, children } のみ（本文は渡されない）。
// sizes は { [id]: { w, h } }、params はこのファイルの layout.params。
var all = [];
(function walk(n) {
  all.push(n);
  if (!n.collapsed) (n.children || []).forEach(walk);
})(tree);

var aStep = Number(params.angleStep)  || 0.6;
var rStep = Number(params.radiusStep) || 42;
var r0    = Number(params.startRadius) || 120;

var positions = {};
all.forEach(function (n, i) {
  var a = i * aStep;
  var r = i === 0 ? 0 : r0 + i * rStep;
  positions[n.id] = { x: r * Math.cos(a), y: r * Math.sin(a) };
});
return { positions: positions };
